import { EventEmitter } from 'events';
import { Logger } from '../logger';
import { ChatClient } from './ChatClient';
import { JanusClient } from './JanusClient';
import { Scraper } from '../../scraper';
import type {
  TurnServersInfo,
  Plugin,
  PluginRegistration,
  AudioDataWithUser,
} from '../types';
import {
  accessChat,
  authorizeToken,
  getTurnServers,
  muteSpeaker,
  negotiateGuestStream,
  setupCommonChatEvents,
  startWatching,
  stopWatching,
  submitSpeakerRequest,
  unmuteSpeaker,
  cancelSpeakerRequest,
} from '../utils';

interface SpaceParticipantConfig {
  spaceId: string;
  debug?: boolean;
}

/**
 * Manages joining an existing Space in listener mode,
 * and optionally becoming a speaker via WebRTC (Janus).
 */
export class SpaceParticipant extends EventEmitter {
  private readonly spaceId: string;
  private readonly debug: boolean;
  private readonly logger: Logger;

  // Basic auth/cookie data
  private cookie?: string;
  private authToken?: string;

  // Chat
  private chatJwtToken?: string;
  private chatToken?: string;
  private chatClient?: ChatClient;

  // Watch session
  private lifecycleToken?: string;
  private watchSession?: string;

  // HLS stream
  private hlsUrl?: string;

  // Speaker request + Janus
  private sessionUUID?: string;
  private janusJwt?: string;
  private webrtcGwUrl?: string;
  private janusClient?: JanusClient;

  // Plugin management
  private plugins = new Set<PluginRegistration>();

  constructor(
    private readonly scraper: Scraper,
    config: SpaceParticipantConfig,
  ) {
    super();
    this.spaceId = config.spaceId;
    this.debug = config.debug ?? false;
    this.logger = new Logger(this.debug);
  }

  /**
   * Adds a plugin and calls its onAttach immediately.
   * init() or onJanusReady() will be invoked later at the appropriate time.
   */
  public use(plugin: Plugin, config?: Record<string, any>) {
    const registration: PluginRegistration = { plugin, config };
    this.plugins.add(registration);

    this.logger.debug(
      '[SpaceParticipant] Plugin added =>',
      plugin.constructor.name,
    );

    // Call the plugin's onAttach if it exists
    plugin.onAttach?.({ space: this, pluginConfig: config });

    return this;
  }

  /**
   * Joins the Space as a listener: obtains HLS, chat token, etc.
   */
  public async joinAsListener(): Promise<void> {
    this.logger.info(
      '[SpaceParticipant] Joining space as listener =>',
      this.spaceId,
    );

    // 1) Get cookie and authorize
    this.cookie = await this.scraper.getPeriscopeCookie();
    this.authToken = await authorizeToken(this.cookie);

    // 2) Retrieve the space metadata for mediaKey
    const spaceMeta = await this.scraper.getAudioSpaceById(this.spaceId);
    const mediaKey = spaceMeta?.metadata?.media_key;
    if (!mediaKey) {
      throw new Error('[SpaceParticipant] No mediaKey found in metadata');
    }
    this.logger.debug('[SpaceParticipant] mediaKey =>', mediaKey);

    // 3) Query live_video_stream/status for HLS URL and chat token
    const status = await this.scraper.getAudioSpaceStreamStatus(mediaKey);
    this.hlsUrl = status?.source?.location;
    this.chatJwtToken = status?.chatToken;
    this.lifecycleToken = status?.lifecycleToken;
    this.logger.debug('[SpaceParticipant] HLS =>', this.hlsUrl);

    // 4) Access the chat
    if (!this.chatJwtToken) {
      throw new Error('[SpaceParticipant] No chatToken found');
    }
    const chatInfo = await accessChat(this.chatJwtToken, this.cookie!);
    this.chatToken = chatInfo.access_token;

    // 5) Create and connect the ChatClient
    this.chatClient = new ChatClient({
      spaceId: chatInfo.room_id,
      accessToken: chatInfo.access_token,
      endpoint: chatInfo.endpoint,
      logger: this.logger,
    });
    await this.chatClient.connect();
    this.setupChatEvents();

    // 6) startWatching (to appear as a viewer)
    this.watchSession = await startWatching(this.lifecycleToken!, this.cookie!);

    this.logger.info('[SpaceParticipant] Joined as listener.');

    // Call plugin.init(...) now that we have basic "listener" mode set up
    for (const { plugin, config } of this.plugins) {
      plugin.init?.({ space: this, pluginConfig: config });
    }
  }

  /**
   * Returns the HLS URL if you want to consume the stream as a listener.
   */
  public getHlsUrl(): string | undefined {
    return this.hlsUrl;
  }

  /**
   * Submits a speaker request using /audiospace/request/submit.
   * Returns the sessionUUID used to track approval.
   */
  public async requestSpeaker(): Promise<{ sessionUUID: string }> {
    if (!this.chatJwtToken) {
      throw new Error(
        '[SpaceParticipant] Must join as listener first (no chat token).',
      );
    }
    if (!this.authToken) {
      throw new Error('[SpaceParticipant] No auth token available.');
    }
    if (!this.chatToken) {
      throw new Error('[SpaceParticipant] No chat token available.');
    }

    this.logger.info('[SpaceParticipant] Submitting speaker request...');

    const { session_uuid } = await submitSpeakerRequest({
      broadcastId: this.spaceId,
      chatToken: this.chatToken,
      authToken: this.authToken,
    });
    this.sessionUUID = session_uuid;

    this.logger.info(
      '[SpaceParticipant] Speaker request submitted =>',
      session_uuid,
    );
    return { sessionUUID: session_uuid };
  }

  /**
   * Cancels a previously submitted speaker request using /audiospace/request/cancel.
   * This requires a valid sessionUUID from requestSpeaker() first.
   */
  public async cancelSpeakerRequest(): Promise<void> {
    if (!this.sessionUUID) {
      throw new Error(
        '[SpaceParticipant] No sessionUUID; cannot cancel a speaker request that was never submitted.',
      );
    }
    if (!this.authToken) {
      throw new Error('[SpaceParticipant] No auth token available.');
    }
    if (!this.chatToken) {
      throw new Error('[SpaceParticipant] No chat token available.');
    }

    await cancelSpeakerRequest({
      broadcastId: this.spaceId,
      sessionUUID: this.sessionUUID,
      chatToken: this.chatToken,
      authToken: this.authToken,
    });

    this.logger.info(
      '[SpaceParticipant] Speaker request canceled =>',
      this.sessionUUID,
    );
    this.sessionUUID = undefined;
  }

  /**
   * Once the host approves our speaker request, we perform Janus negotiation
   * to become a speaker.
   */
  public async becomeSpeaker(): Promise<void> {
    if (!this.sessionUUID) {
      throw new Error(
        '[SpaceParticipant] No sessionUUID (did you call requestSpeaker()?).',
      );
    }
    this.logger.info(
      '[SpaceParticipant] Negotiating speaker role via Janus...',
    );

    // 1) Retrieve TURN servers
    const turnServers: TurnServersInfo = await getTurnServers(this.cookie!);
    this.logger.debug('[SpaceParticipant] turnServers =>', turnServers);

    // 2) Negotiate with /audiospace/stream/negotiate
    const nego = await negotiateGuestStream({
      broadcastId: this.spaceId,
      sessionUUID: this.sessionUUID,
      authToken: this.authToken!,
      cookie: this.cookie!,
    });
    this.janusJwt = nego.janus_jwt;
    this.webrtcGwUrl = nego.webrtc_gw_url;
    this.logger.debug('[SpaceParticipant] webrtcGwUrl =>', this.webrtcGwUrl);

    // 3) Create JanusClient
    this.janusClient = new JanusClient({
      webrtcUrl: this.webrtcGwUrl!,
      roomId: this.spaceId,
      credential: this.janusJwt!,
      userId: turnServers.username.split(':')[1],
      streamName: this.spaceId,
      turnServers,
      logger: this.logger,
    });

    // 4) Initialize the guest speaker session in Janus
    await this.janusClient.initializeGuestSpeaker(this.sessionUUID);

    this.janusClient.on('audioDataFromSpeaker', (data: AudioDataWithUser) => {
      this.logger.debug(
        '[SpaceParticipant] Received speaker audio =>',
        data.userId,
      );
      this.handleAudioData(data);
    });

    this.logger.info(
      '[SpaceParticipant] Now speaker on the Space =>',
      this.spaceId,
    );

    // For plugins that need direct Janus references, call onJanusReady
    for (const { plugin } of this.plugins) {
      plugin.onJanusReady?.(this.janusClient);
    }
  }

  /**
   * Leaves the Space gracefully:
   * - Stop Janus if we were a speaker
   * - Stop watching as a viewer
   * - Disconnect chat
   */
  public async leaveSpace(): Promise<void> {
    this.logger.info('[SpaceParticipant] Leaving space...');

    // If speaker, stop Janus
    if (this.janusClient) {
      await this.janusClient.stop();
      this.janusClient = undefined;
    }

    // Stop watching
    if (this.watchSession && this.cookie) {
      await stopWatching(this.watchSession, this.cookie);
    }

    // Disconnect chat
    if (this.chatClient) {
      await this.chatClient.disconnect();
      this.chatClient = undefined;
    }

    this.logger.info('[SpaceParticipant] Left space =>', this.spaceId);
  }

  /**
   * Pushes PCM audio frames if we're speaker; otherwise logs a warning.
   */
  public pushAudio(samples: Int16Array, sampleRate: number) {
    if (!this.janusClient) {
      this.logger.warn(
        '[SpaceParticipant] Not a speaker yet; ignoring pushAudio.',
      );
      return;
    }
    this.janusClient.pushLocalAudio(samples, sampleRate);
  }

  /**
   * Internal handler for incoming PCM frames from Janus, forwarded to plugin.onAudioData if present.
   */
  private handleAudioData(data: AudioDataWithUser) {
    for (const { plugin } of this.plugins) {
      plugin.onAudioData?.(data);
    }
  }

  /**
   * Sets up chat events: "occupancyUpdate", "newSpeakerAccepted", etc.
   */
  private setupChatEvents() {
    if (!this.chatClient) return;
    setupCommonChatEvents(this.chatClient, this.logger, this);

    this.chatClient.on('newSpeakerAccepted', ({ userId }) => {
      this.logger.debug('[SpaceParticipant] newSpeakerAccepted =>', userId);

      // If we haven't created Janus yet, skip
      if (!this.janusClient) {
        this.logger.warn(
          '[SpaceParticipant] No janusClient yet; ignoring new speaker...',
        );
        return;
      }
      // If this is our own handle, skip
      if (userId === this.janusClient.getHandleId()) {
        return;
      }

      // Subscribe to this new speaker's audio
      this.janusClient.subscribeSpeaker(userId).catch((err) => {
        this.logger.error('[SpaceParticipant] subscribeSpeaker error =>', err);
      });
    });
  }

  /**
   * Mute self if we are speaker: calls /audiospace/muteSpeaker with our sessionUUID.
   */
  public async muteSelf(): Promise<void> {
    if (!this.authToken || !this.chatToken) {
      throw new Error('[SpaceParticipant] Missing authToken or chatToken.');
    }
    if (!this.sessionUUID) {
      throw new Error('[SpaceParticipant] No sessionUUID; are you a speaker?');
    }

    await muteSpeaker({
      broadcastId: this.spaceId,
      sessionUUID: this.sessionUUID,
      chatToken: this.chatToken,
      authToken: this.authToken,
    });
    this.logger.info('[SpaceParticipant] Successfully muted self.');
  }

  /**
   * Unmute self if we are speaker: calls /audiospace/unmuteSpeaker with our sessionUUID.
   */
  public async unmuteSelf(): Promise<void> {
    if (!this.authToken || !this.chatToken) {
      throw new Error('[SpaceParticipant] Missing authToken or chatToken.');
    }
    if (!this.sessionUUID) {
      throw new Error('[SpaceParticipant] No sessionUUID; are you a speaker?');
    }

    await unmuteSpeaker({
      broadcastId: this.spaceId,
      sessionUUID: this.sessionUUID,
      chatToken: this.chatToken,
      authToken: this.authToken,
    });
    this.logger.info('[SpaceParticipant] Successfully unmuted self.');
  }
}

import tls from 'node:tls';
import { randomBytes } from 'node:crypto';

const ORIGINAL_CIPHERS = tls.DEFAULT_CIPHERS;

// How many ciphers from the top of the list to shuffle.
// The remaining ciphers are left in the original order.
const TOP_N_SHUFFLE = 8;

// Modified variation of https://stackoverflow.com/a/12646864
const shuffleArray = (array: unknown[]) => {
  for (let i = array.length - 1; i > 0; i--) {
    const j = randomBytes(4).readUint32LE() % array.length;
    [array[i], array[j]] = [array[j], array[i]];
  }

  return array;
};

// https://github.com/imputnet/cobalt/pull/574
export const randomizeCiphers = () => {
  do {
    const cipherList = ORIGINAL_CIPHERS.split(':');
    const shuffled = shuffleArray(cipherList.slice(0, TOP_N_SHUFFLE));
    const retained = cipherList.slice(TOP_N_SHUFFLE);

    tls.DEFAULT_CIPHERS = [...shuffled, ...retained].join(':');
  } while (tls.DEFAULT_CIPHERS === ORIGINAL_CIPHERS);
};

# agent-twitter-client

This is a modified version of [@the-convocation/twitter-scraper](https://github.com/the-convocation/twitter-scraper) with added functionality for sending tweets and retweets. This package does not require the Twitter API to use and will run in both the browser and server.

## Installation

```sh
npm install agent-twitter-client
```

## Setup

Configure environment variables for authentication.

```
TWITTER_USERNAME=    # Account username
TWITTER_PASSWORD=    # Account password
TWITTER_EMAIL=       # Account email
PROXY_URL=           # HTTP(s) proxy for requests (necessary for browsers)

# Twitter API v2 credentials for tweet and poll functionality
TWITTER_API_KEY=               # Twitter API Key
TWITTER_API_SECRET_KEY=        # Twitter API Secret Key
TWITTER_ACCESS_TOKEN=          # Access Token for Twitter API v2
TWITTER_ACCESS_TOKEN_SECRET=   # Access Token Secret for Twitter API v2
```

### Getting Twitter Cookies

It is important to use Twitter cookies to avoid sending a new login request to Twitter every time you want to perform an action.

In your application, you will likely want to check for existing cookies. If cookies are not available, log in with user authentication credentials and cache the cookies for future use.

```ts
const scraper = await getScraper({ authMethod: 'password' });

scraper.getCookies().then((cookies) => {
  console.log(cookies);
  // Remove 'Cookies' and save the cookies as a JSON array
});
```

## Getting Started

```ts
const scraper = new Scraper();
await scraper.login('username', 'password');

// If using v2 functionality (currently required to support polls)
await scraper.login(
  'username',
  'password',
  'email',
  'appKey',
  'appSecret',
  'accessToken',
  'accessSecret',
);

const tweets = await scraper.getTweets('elonmusk', 10);
const tweetsAndReplies = scraper.getTweetsAndReplies('elonmusk');
const latestTweet = await scraper.getLatestTweet('elonmusk');
const tweet = await scraper.getTweet('1234567890123456789');
await scraper.sendTweet('Hello world!');

// Create a poll
await scraper.sendTweetV2(
  `What's got you most hyped? Let us know! 🤖💸`,
  undefined,
  {
    poll: {
      options: [
        { label: 'AI Innovations 🤖' },
        { label: 'Crypto Craze 💸' },
        { label: 'Both! 🌌' },
        { label: 'Neither for Me 😅' },
      ],
      durationMinutes: 120, // Duration of the poll in minutes
    },
  },
);
```

### Fetching Specific Tweet Data (V2)

```ts
// Fetch a single tweet with poll details
const tweet = await scraper.getTweetV2('1856441982811529619', {
  expansions: ['attachments.poll_ids'],
  pollFields: ['options', 'end_datetime'],
});
console.log('tweet', tweet);

// Fetch multiple tweets with poll and media details
const tweets = await scraper.getTweetsV2(
  ['1856441982811529619', '1856429655215260130'],
  {
    expansions: ['attachments.poll_ids', 'attachments.media_keys'],
    pollFields: ['options', 'end_datetime'],
    mediaFields: ['url', 'preview_image_url'],
  },
);
console.log('tweets', tweets);
```

## API

### Authentication

```ts
// Log in
await scraper.login('username', 'password');

// Log out
await scraper.logout();

// Check if logged in
const isLoggedIn = await scraper.isLoggedIn();

// Get current session cookies
const cookies = await scraper.getCookies();

// Set current session cookies
await scraper.setCookies(cookies);

// Clear current cookies
await scraper.clearCookies();
```

### Profile

```ts
// Get a user's profile
const profile = await scraper.getProfile('TwitterDev');

// Get a user ID from their screen name
const userId = await scraper.getUserIdByScreenName('TwitterDev');

// Get logged-in user's profile
const me = await scraper.me();
```

### Search

```ts
import { SearchMode } from 'agent-twitter-client';

// Search for recent tweets
const tweets = scraper.searchTweets('#nodejs', 20, SearchMode.Latest);

// Search for profiles
const profiles = scraper.searchProfiles('John', 10);

// Fetch a page of tweet results
const results = await scraper.fetchSearchTweets('#nodejs', 20, SearchMode.Top);

// Fetch a page of profile results
const profileResults = await scraper.fetchSearchProfiles('John', 10);
```

### Relationships

```ts
// Get a user's followers
const followers = scraper.getFollowers('12345', 100);

// Get who a user is following
const following = scraper.getFollowing('12345', 100);

// Fetch a page of a user's followers
const followerResults = await scraper.fetchProfileFollowers('12345', 100);

// Fetch a page of who a user is following
const followingResults = await scraper.fetchProfileFollowing('12345', 100);

// Follow a user
const followUserResults = await scraper.followUser('elonmusk');
```

### Trends

```ts
// Get current trends
const trends = await scraper.getTrends();

// Fetch tweets from a list
const listTweets = await scraper.fetchListTweets('1234567890', 50);
```

### Tweets

```ts
// Get a user's tweets
const tweets = scraper.getTweets('TwitterDev');

// Fetch the home timeline
const homeTimeline = await scraper.fetchHomeTimeline(10, ['seenTweetId1','seenTweetId2']);

// Get a user's liked tweets
const likedTweets = scraper.getLikedTweets('TwitterDev');

// Get a user's tweets and replies
const tweetsAndReplies = scraper.getTweetsAndReplies('TwitterDev');

// Get tweets matching specific criteria
const timeline = scraper.getTweets('TwitterDev', 100);
const retweets = await scraper.getTweetsWhere(
  timeline,
  (tweet) => tweet.isRetweet,
);

// Get a user's latest tweet
const latestTweet = await scraper.getLatestTweet('TwitterDev');

// Get a specific tweet by ID
const tweet = await scraper.getTweet('1234567890123456789');

// Send a tweet
const sendTweetResults = await scraper.sendTweet('Hello world!');

// Send a quote tweet - Media files are optional
const sendQuoteTweetResults = await scraper.sendQuoteTweet(
  'Hello world!',
  '1234567890123456789',
  ['mediaFile1', 'mediaFile2'],
);

// Retweet a tweet
const retweetResults = await scraper.retweet('1234567890123456789');

// Like a tweet
const likeTweetResults = await scraper.likeTweet('1234567890123456789');
```

## Sending Tweets with Media

### Media Handling

The scraper requires media files to be processed into a specific format before sending:

- Media must be converted to Buffer format
- Each media file needs its MIME type specified
- This helps the scraper distinguish between image and video processing models

### Basic Tweet with Media

```ts
// Example: Sending a tweet with media attachments
const mediaData = [
  {
    data: fs.readFileSync('path/to/image.jpg'),
    mediaType: 'image/jpeg',
  },
  {
    data: fs.readFileSync('path/to/video.mp4'),
    mediaType: 'video/mp4',
  },
];

await scraper.sendTweet('Hello world!', undefined, mediaData);
```

### Supported Media Types

```ts
// Image formats and their MIME types
const imageTypes = {
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.png': 'image/png',
  '.gif': 'image/gif',
};

// Video format
const videoTypes = {
  '.mp4': 'video/mp4',
};
```

### Media Upload Limitations

- Maximum 4 images per tweet
- Only 1 video per tweet
- Maximum video file size: 512MB
- Supported image formats: JPG, PNG, GIF
- Supported video format: MP4

## Grok Integration

This client provides programmatic access to Grok through Twitter's interface, offering a unique capability that even Grok's official API cannot match - access to real-time Twitter data. While Grok has a standalone API, only by interacting with Grok through Twitter can you leverage its ability to analyze and respond to live Twitter content. This makes it the only way to programmatically access an LLM with direct insight into Twitter's real-time information. [@grokkyAi](https://x.com/grokkyAi)

### Basic Usage

```ts
const scraper = new Scraper();
await scraper.login('username', 'password');

// Start a new conversation
const response = await scraper.grokChat({
  messages: [{ role: 'user', content: 'What are your thoughts on AI?' }],
});

console.log(response.message); // Grok's response
console.log(response.messages); // Full conversation history
```

If no `conversationId` is provided, the client will automatically create a new conversation.

### Handling Rate Limits

Grok has rate limits of 25 messages every 2 hours for non-premium accounts. The client provides rate limit information in the response:

```ts
const response = await scraper.grokChat({
  messages: [{ role: 'user', content: 'Hello!' }],
});

if (response.rateLimit?.isRateLimited) {
  console.log(response.rateLimit.message);
  console.log(response.rateLimit.upsellInfo); // Premium upgrade information
}
```

### Response Types

The Grok integration includes TypeScript types for better development experience:

```ts
interface GrokChatOptions {
  messages: GrokMessage[];
  conversationId?: string;
  returnSearchResults?: boolean;
  returnCitations?: boolean;
}

interface GrokChatResponse {
  conversationId: string;
  message: string;
  messages: GrokMessage[];
  webResults?: any[];
  metadata?: any;
  rateLimit?: GrokRateLimit;
}
```

### Advanced Usage

```ts
const response = await scraper.grokChat({
  messages: [{ role: 'user', content: 'Research quantum computing' }],
  returnSearchResults: true, // Include web search results
  returnCitations: true, // Include citations for information
});

// Access web results if available
if (response.webResults) {
  console.log('Sources:', response.webResults);
}

// Full conversation with history
console.log('Conversation:', response.messages);
```

### Limitations

- Message history prefilling is currently limited due to unofficial API usage
- Rate limits are enforced (25 messages/2 hours for non-premium)

import { ProxyAgent,setGlobalDispatcher } from 'undici';
import { Scraper } from './scraper';
import fs from 'fs';

export interface ScraperTestOptions {
  /**
   * Authentication method preference for the scraper.
   * - 'api': Use Twitter API keys and tokens.
   * - 'cookies': Resume session using cookies.
   * - 'password': Use username/password for login.
   * - 'anonymous': No authentication.
   */
  authMethod: 'api' | 'cookies' | 'password' | 'anonymous';
}

export async function getScraper(
  options: Partial<ScraperTestOptions> = { authMethod: 'cookies' },
) {
  const username = process.env['TWITTER_USERNAME'];
  const password = process.env['TWITTER_PASSWORD'];
  const email = process.env['TWITTER_EMAIL'];
  const twoFactorSecret = process.env['TWITTER_2FA_SECRET'];

  const apiKey = process.env['TWITTER_API_KEY'];
  const apiSecretKey = process.env['TWITTER_API_SECRET_KEY'];
  const accessToken = process.env['TWITTER_ACCESS_TOKEN'];
  const accessTokenSecret = process.env['TWITTER_ACCESS_TOKEN_SECRET'];

  let cookiesArray: any = null;

  // try to read cookies by reading cookies.json with fs and parsing
  // check if cookies.json exists
  if (!fs.existsSync('./cookies.json')) {
    console.error(
      'cookies.json not found, using password auth - this is NOT recommended!',
    );
  } else {
    try {
      const cookiesText = fs.readFileSync('./cookies.json', 'utf8');
      cookiesArray = JSON.parse(cookiesText);
    } catch (e) {
      console.error('Error parsing cookies.json', e);
    }
  }

  const cookieStrings = cookiesArray?.map(
    (cookie: any) =>
      `${cookie.key}=${cookie.value}; Domain=${cookie.domain}; Path=${
        cookie.path
      }; ${cookie.secure ? 'Secure' : ''}; ${
        cookie.httpOnly ? 'HttpOnly' : ''
      }; SameSite=${cookie.sameSite || 'Lax'}`,
  );

  const proxyUrl = process.env['PROXY_URL'];
  let agent: any;

  if (
    options.authMethod === 'cookies' &&
    (!cookieStrings || cookieStrings.length === 0)
  ) {
    console.warn(
      'TWITTER_COOKIES variable is not defined, reverting to password auth (not recommended)',
    );
    options.authMethod = 'password';
  }

  if (options.authMethod === 'password' && !(username && password)) {
    throw new Error(
      'TWITTER_USERNAME and TWITTER_PASSWORD variables must be defined.',
    );
  }

  if (proxyUrl) {
    // Parse the proxy URL
    const url = new URL(proxyUrl);
    const username = url.username;
    const password = url.password;

    // Strip auth from URL if present
    url.username = '';
    url.password = '';

    const agentOptions: any = {
      uri: url.toString(),
      requestTls: {
        rejectUnauthorized: false,
      },
    };

    // Add Basic auth if credentials exist
    if (username && password) {
      agentOptions.token = `Basic ${Buffer.from(
        `${username}:${password}`,
      ).toString('base64')}`;
    }

    agent = new ProxyAgent(agentOptions);

    setGlobalDispatcher(agent)
  }

  const scraper = new Scraper({
    transform: {
      request: (input, init) => {
        if (agent) {
          return [input, { ...init, dispatcher: agent }];
        }
        return [input, init];
      },
    },
  });

  if (
    options.authMethod === 'api' &&
    username &&
    password &&
    apiKey &&
    apiSecretKey &&
    accessToken &&
    accessTokenSecret
  ) {
    await scraper.login(
      username,
      password,
      email,
      twoFactorSecret,
      apiKey,
      apiSecretKey,
      accessToken,
      accessTokenSecret,
    );
  } else if (options.authMethod === 'cookies' && cookieStrings?.length) {
    await scraper.setCookies(cookieStrings);
  } else if (options.authMethod === 'password' && username && password) {
    await scraper.login(username, password, email, twoFactorSecret);
  } else {
    console.warn(
      'No valid authentication method available. Ensure at least one of the following is configured: API credentials, cookies, or username/password.',
    );
  }

  return scraper;
}

